-- The privacy text now says questions go to an external AI provider and that redaction is best-effort.
-- Only the text the seed installed is replaced, so an admin's own wording is kept.
UPDATE site_settings SET value = '{"th": "คำถามที่ส่งถึงผู้ช่วย AI จะถูกส่งไปยังผู้ให้บริการ AI ภายนอกเพื่อสร้างคำตอบ ระบบพยายามลบเบอร์โทร อีเมล เลขบัตรประชาชน และเลขบัญชีออกก่อนส่งและก่อนบันทึก แต่ไม่สามารถรับประกันได้ว่าลบได้ทั้งหมด จึงไม่ควรพิมพ์ชื่อ ที่อยู่ หรือข้อมูลติดต่อ คำถามที่บันทึกจะถูกลบอัตโนมัติเมื่อครบ 180 วัน แบบสอบถามวิจัยไม่เก็บชื่อหรือข้อมูลติดต่อ แต่ข้อความที่พิมพ์เองอาจมีข้อมูลส่วนตัว จึงควรหลีกเลี่ยง", "zh": "发送给AI助手的问题会传送给外部AI服务商以生成回答。系统会在发送和保存前尝试删除电话、邮箱、身份证和银行账号，但不能保证全部删除。请勿输入姓名、住址或联系方式。保存的问题将在180天后自动删除。问卷不收集姓名或联系方式，但自由填写的内容可能含有个人信息，请避免填写。", "en": "Questions sent to the AI assistant are passed to an external AI provider to generate answers. The system tries to remove phone numbers, emails, ID numbers and bank accounts before sending and before storage, but cannot guarantee that all are removed. Do not type names, addresses or contact details. Stored questions are deleted automatically after 180 days. The survey does not collect names or contact details, but free-text comments may still contain personal information, so please avoid them."}'::jsonb
WHERE key = 'privacy' AND value->>'en' LIKE 'We do not collect names%';
